-- PostgreSQL 16 schema reconstructed for data quality work.
-- Source: IMS_Data_Dictionary.xlsx, Columns and Relationships sheets.
-- Django field names map to physical columns using the default _id suffix
-- for ForeignKey and OneToOne fields. Unspecified char lengths and decimal
-- precision are unbounded. No application defaults or undocumented indexes
-- and constraints are inferred. See README.md for remaining assumptions.

BEGIN;
CREATE SCHEMA ims;

CREATE TABLE ims."administration_country" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "country" varchar NOT NULL,
    "countrycode" varchar,
    "mifos_pk" integer,
    "notes" text
);

CREATE TABLE ims."administration_itemframework" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "parent_id" bigint,
    "itemname" varchar NOT NULL,
    "itemid" varchar,
    "disabled" boolean NOT NULL,
    "expanded" boolean NOT NULL,
    "leaf" boolean NOT NULL,
    "iconcls" varchar,
    "viewfunction" varchar,
    "desc" text,
    "parent_itemcode" varchar,
    "parent_iconcls" varchar
);

CREATE TABLE ims."administration_roleoperations" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_role_id" bigint NOT NULL,
    "menu_item_id" bigint NOT NULL,
    "view_perm" boolean NOT NULL,
    "add_perm" boolean NOT NULL,
    "edit_perm" boolean NOT NULL,
    "delete_perm" boolean NOT NULL
);

CREATE TABLE ims."administration_userprofile" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" integer NOT NULL,
    "role_id" bigint,
    "location" text NOT NULL,
    "phone_number" text,
    "office_phone" text,
    "api_allowed" boolean NOT NULL,
    "api_user" varchar,
    "api_key" varchar,
    "user_timezone" varchar
);

CREATE TABLE ims."administration_userroles" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "rolename" varchar NOT NULL,
    "description" text,
    "default_role" boolean NOT NULL,
    "deleted" boolean NOT NULL
);

CREATE TABLE ims."administration_year" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "year" integer NOT NULL,
    "notes" text
);

CREATE TABLE ims."auth_group" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar NOT NULL
);

CREATE TABLE ims."auth_permission" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" varchar NOT NULL,
    "content_type_id" integer NOT NULL,
    "codename" varchar NOT NULL
);

CREATE TABLE ims."auth_user" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "password" varchar NOT NULL,
    "last_login" timestamp with time zone,
    "is_superuser" boolean NOT NULL,
    "username" varchar NOT NULL,
    "first_name" varchar NOT NULL,
    "last_name" varchar NOT NULL,
    "email" varchar NOT NULL,
    "is_staff" boolean NOT NULL,
    "is_active" boolean NOT NULL,
    "date_joined" timestamp with time zone NOT NULL
);

CREATE TABLE ims."authtoken_token" (
    "key" varchar PRIMARY KEY,
    "user_id" integer UNIQUE NOT NULL,
    "created" timestamp with time zone NOT NULL
);

CREATE TABLE ims."bgs_administrativedivisions" (
    "id" uuid PRIMARY KEY,
    "country_id" bigint,
    "parent_id" uuid,
    "name" varchar NOT NULL,
    "code" varchar,
