-- Delete and update use NO ACTION. Transaction deferral follows Django's
-- PostgreSQL convention. Application-level on_delete rules are unspecified.
ALTER TABLE ims."administration_itemframework"
    ADD FOREIGN KEY ("parent_id") REFERENCES ims."administration_itemframework" ("id")
